    static extern IntPtr GetConsoleWindow();

    [DllImport("user32.dll")]
    static extern bool IsConsoleVisible(int dwFlags);

    [DllImport("user32.dll")]
    static extern bool SetConsoleMode(IntPtr hConsole, int dwMode);

    [DllImport("user32.dll")]
    static extern void GetConsoleInputInfo(IntPtr hConsoleInput, ref ConsoleInputInfo ci);
}

